const enrichItemsWithCalculations = (itemList: DocItem[], showInRtl: boolean, columns?: any[]): DocItem[] => {
  return itemList.map(item => {
    const newItem = { ...item };

    // Recursive helper to safely get parent value at any depth
    const getParentFieldValue = (pId: string, fieldKey: string): string => {
      const p = itemList.find(r => r.id === pId);
      if (!p) return '';
      return (p[fieldKey] as string) ?? '';
    };

    // Resolve sub-group parent replication dynamically to write back to database completely
    if (newItem.parentId) {
      if (newItem.subGroupColId) {
        if (columns && columns.length > 0) {
          const matchingCol = columns.find(c => c.id === newItem.subGroupColId || c.field === newItem.subGroupColId);
          if (matchingCol) {
            newItem[matchingCol.field] = getParentFieldValue(newItem.parentId, matchingCol.field);
          }
        } else {
          const subMatch = newItem.subGroupColId.match(/field(\d+)/);
          if (subMatch) {
            const fKey = `field${subMatch[1]}` as keyof DocItem;
            newItem[fKey] = getParentFieldValue(newItem.parentId, fKey as string);
          }
        }
      } else {
        const fieldsToCopy = ['field1', 'field2'];
        fieldsToCopy.forEach(f => {
          const fKey = f as keyof DocItem;
          if (!newItem[fKey]) {
            newItem[fKey] = getParentFieldValue(newItem.parentId!, f);
          }
        });
      }
    }

    // 1. final_score
    const finalScore = ((newItem.weight || 0) * (newItem.rating || 0));
    newItem['final_score'] = parseFloat(finalScore.toFixed(2));

    // 2. rpn
    const rpn = (newItem.severity || 1) * (newItem.occurrence || 1) * (newItem.detection || 1);
    newItem['rpn'] = rpn;

    // 3. measured_error
    const measuredErr = Math.abs(Number(newItem.readValue || 0) - Number(newItem.refValue || 0));
    newItem['measured_error'] = parseFloat(measuredErr.toFixed(4));

    // 4. calibration_status
    const mpe = Number(newItem.mpe || 0.001);
    const pass = measuredErr <= mpe;
    newItem['calibration_status'] = pass 
      ? (showInRtl ? 'منطبق (Pass)' : 'Pass') 
      : (showInRtl ? 'مردود (Fail)' : 'Fail');

    // 5. kpi_rate
    const target = Number(newItem.target || 0);
    const actual = Number(newItem.actual || 0);
    let rate = 0;
    if (target > 0) {
      const isPPM = newItem.unit === 'PPM' || 
        (newItem.field1 && newItem.field1.includes('PPM')) || 
        (newItem.field1 && newItem.field1.includes('ضایعات')) || 
        (newItem.field1 && newItem.field1.includes('خرابی')) ||
        (newItem.field1 && newItem.field1.toLowerCase().includes('scrap')) ||
        (newItem.field1 && newItem.field1.toLowerCase().includes('defect'));

      if (isPPM) {
        rate = actual <= target ? 100 : (target / actual) * 100;
      } else {
        rate = (actual / target) * 100;
      }
      if (rate > 100) rate = 100;
    }
    newItem['kpi_rate'] = rate.toFixed(1) + '%';

    // 6. spc_stats
    const vals = (newItem.measurements || '').split(',').map((v: string) => parseFloat(v.trim())).filter((v: number) => !isNaN(v));
    if (vals.length >= 3) {
      const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
      const variance = vals.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / (vals.length - 1);
      const sigma = Math.sqrt(variance);
      newItem['spc_stats'] = `${showInRtl ? 'میانگین' : 'Mean'}: ${mean.toFixed(3)} | ${showInRtl ? 'انحراف' : 'StdDev'}: ${sigma.toFixed(4)}`;
    } else {
      newItem['spc_stats'] = showInRtl ? 'داده ناکافی' : 'Insufficient data';
    }

    // 7. spc_cpk
    if (vals.length >= 3) {
      const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
      const variance = vals.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / (vals.length - 1);
      const sigma = Math.sqrt(variance);
      if (sigma > 0) {
        const usl = Number(newItem.usl || 0);
        const lsl = Number(newItem.lsl || 0);
        const cpu = (usl - mean) / (3 * sigma);
        const cpl = (mean - lsl) / (3 * sigma);
        const cpk = Math.min(cpu, cpl);
        const verified = cpk >= 1.33;
        newItem['spc_cpk'] = `Cp: ${( (usl - lsl) / (6 * sigma) ).toFixed(2)}, Cpk: ${cpk.toFixed(2)} ${verified ? '✓' : '⚠️'}`;
      } else {
        newItem['spc_cpk'] = 'N/A';
      }
    } else {
      newItem['spc_cpk'] = 'N/A';
    }

    // 8. grr
    const ev = Number(newItem.evValue || 0);
    const av = Number(newItem.avValue || 0);
    const grrVal = Math.sqrt(ev * ev + av * av);
    newItem['grr'] = grrVal.toFixed(2) + '%';

    // 9. msa_status
    let msa_label = showInRtl ? "تایید شده (عالی)" : "Accepted (Excellent)";
    if (grrVal > 30) {
      msa_label = showInRtl ? "مردود (نامناسب)" : "Rejected (Unacceptable)";
    } else if (grrVal >= 10) {
      msa_label = showInRtl ? "تایید مشروط (پایش)" : "Conditional (Monitor)";
    }
    newItem['msa_status'] = msa_label;

    return newItem;
  });
};

