  // Column Math Operations State
  const [colOperations, setColOperations] = useState<Record<string, 'none' | 'sum' | 'avg' | 'min' | 'max' | 'count' | 'std' | 'var'>>(() => {
    try {
      const saved = localStorage.getItem(`col_ops_${template.title}`);
      return saved ? JSON.parse(saved) : {};
    } catch {
      return {};
    }
  });

  const [showColMathFooter, setShowColMathFooter] = useState<boolean>(true);

  const updateColOperation = (colId: string, operation: 'none' | 'sum' | 'avg' | 'min' | 'max' | 'count' | 'std' | 'var') => {
    const nextOps = { ...colOperations, [colId]: operation };
    setColOperations(nextOps);
    try {
      localStorage.setItem(`col_ops_${template.title}`, JSON.stringify(nextOps));
    } catch {}
  };

  const calculateColumnOperation = (colId: string, operation: 'none' | 'sum' | 'avg' | 'min' | 'max' | 'count' | 'std' | 'var') => {
    const colDef = columns.find(c => c.id === colId);
    if (!colDef) return '—';
    
    // Support standard numeric/formula types AND automatic numeric display columns (like final_score, rpn, measured_error, kpi_rate, grr)
    const isAutoCalculatedNumeric = ['final_score', 'rpn', 'measured_error', 'kpi_rate', 'grr'].includes(colId) || ['final_score', 'rpn', 'measured_error', 'kpi_rate', 'grr'].includes(colDef.field || '');
    if (colDef.type !== 'number' && colDef.type !== 'formula' && !isAutoCalculatedNumeric) {
      return '—';
    }

    const fieldName = colDef.field || colId;
    
    const parseNumber = (val: any): number | null => {
      if (val === undefined || val === null) return null;
      let str = String(val).trim();
      str = str.replace(/,/g, '');
      if (str.endsWith('%')) {
        str = str.slice(0, -1).trim();
      }
      const parsed = parseFloat(str);
      return isNaN(parsed) ? null : parsed;
    };

    const numbers = filteredItems
      .map(item => {
        const val = item[fieldName] !== undefined ? item[fieldName] : item[colId];
        return parseNumber(val);
      })
      .filter((v): v is number => v !== null);

    if (numbers.length === 0) return '—';

    let resultValue = '';
    switch (operation) {
      case 'sum': {
        const sum = numbers.reduce((acc, val) => acc + val, 0);
        resultValue = Number(sum.toFixed(4)).toString();
        break;
      }
      case 'avg': {
        const sum = numbers.reduce((acc, val) => acc + val, 0);
        resultValue = Number((sum / numbers.length).toFixed(4)).toString();
        break;
      }
      case 'min': {
        const minVal = Math.min(...numbers);
        resultValue = Number(minVal.toFixed(4)).toString();
        break;
      }
      case 'max': {
        const maxVal = Math.max(...numbers);
        resultValue = Number(maxVal.toFixed(4)).toString();
        break;
      }
      case 'count': {
        return numbers.length.toString();
      }
      case 'std': {
        if (numbers.length < 2) return '0';
        const sum = numbers.reduce((acc, val) => acc + val, 0);
        const mean = sum / numbers.length;
        const sqDiffsSum = numbers.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0);
        const variance = sqDiffsSum / (numbers.length - 1);
        resultValue = Number(Math.sqrt(variance).toFixed(4)).toString();
        break;
      }
      case 'var': {
        if (numbers.length < 2) return '0';
        const sum = numbers.reduce((acc, val) => acc + val, 0);
        const mean = sum / numbers.length;
        const sqDiffsSum = numbers.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0);
        const variance = sqDiffsSum / (numbers.length - 1);
        resultValue = Number(variance.toFixed(4)).toString();
        break;
      }
      default:
        return '';
    }

    const isPercentage = colId === 'kpi_rate' || colId === 'grr' || (colDef && (colDef.id === 'kpi_rate' || colDef.id === 'grr'));
    if (isPercentage) {
      return `${resultValue}%`;
    }
    return resultValue;
  };

  // Dynamic cross-referencing system to find live associations across all tables/sheets in the database
  const getRowDbConnections = (currentDocTitle: string, item: any, currentColumns: ColumnDefinition[]): DBConnectionLink[] => {
    const links: DBConnectionLink[] = [];
    const allDocs = QmsDatabase.selectAll('documents_table') || {};
    
    // 1. OUTGOING CONNECTIONS (References other tables)
    currentColumns.forEach(col => {
      if (col.type === 'db_lookup' && col.dbTable && col.dbColumn) {
        const fkVal = item[col.field + '_fk'];
        if (fkVal) {
          let targetDocName = col.dbTable;
          let isDoc = false;
          if (col.dbTable.startsWith('doc_')) {
            targetDocName = col.dbTable.substring(4);
            isDoc = true;
          }
          
          let targetRowLabel = String(fkVal);
          let foundRow: any = null;
          
          if (isDoc) {
            let docRows = allDocs[targetDocName] || [];
            if (docRows.length === 0) {
              try {
                const draftItemsRaw = localStorage.getItem(`iatf_draft_items_${targetDocName}`);
                if (draftItemsRaw) docRows = JSON.parse(draftItemsRaw);
              } catch {}
            }
            foundRow = docRows.find((r: any) => String(r.id) === String(fkVal));
            if (foundRow) {
              const val = col.dbColumn ? foundRow[col.dbColumn] : null;
              targetRowLabel = (val !== undefined && val !== null && String(val).trim() !== '')
                ? String(val)
                : String(foundRow.clause || foundRow.title || foundRow.description || foundRow.details || foundRow.name || foundRow.field1 || foundRow.field2 || foundRow.id);
            }
          } else {
            const dbTableData = QmsDatabase.selectAll(col.dbTable as any) || {};
            foundRow = dbTableData[fkVal];
            if (foundRow) {
              const val = col.dbColumn && typeof foundRow === 'object' ? foundRow[col.dbColumn] : null;
              targetRowLabel = (val !== undefined && val !== null && String(val).trim() !== '')
                ? String(val)
                : String(fkVal);
            }
          }
          
          links.push({
            docTitle: targetDocName,
            rowId: String(fkVal),
            rowLabel: targetRowLabel,
            relationType: 'references',
            relationLabel: isRtl ? `مرجع اصلی (ستون ${col.label})` : `Reference source (Col: ${col.label})`
          });
        }
      }
    });

    // 2. INCOMING CONNECTIONS (Other tables referencing this table)
    Object.keys(allDocs).forEach(otherDocTitle => {
      if (otherDocTitle === currentDocTitle) return;
      
      let otherCols: ColumnDefinition[] = [];
      try {
        const otherColsRaw = localStorage.getItem(`iatf_draft_cols_${otherDocTitle}`);
        if (otherColsRaw) {
          otherCols = JSON.parse(otherColsRaw);
        }
      } catch {}
      
      if (!Array.isArray(otherCols) || otherCols.length === 0) {
        const otherTpl = documentTemplates[otherDocTitle];
        if (otherTpl) {
          otherCols = getInitialColumns(otherTpl);
        }
      }
      
      otherCols.forEach(otherCol => {
        const isRef = otherCol.type === 'db_lookup' && 
                      otherCol.dbTable && 
                      (otherCol.dbTable === `doc_${currentDocTitle}` || otherCol.dbTable === currentDocTitle);
                      
        if (isRef) {
          let otherDocRows = allDocs[otherDocTitle] || [];
          if (otherDocRows.length === 0) {
            try {
              const draftItemsRaw = localStorage.getItem(`iatf_draft_items_${otherDocTitle}`);
              if (draftItemsRaw) otherDocRows = JSON.parse(draftItemsRaw);
            } catch {}
          }
          
          otherDocRows.forEach((otherRow: any) => {
            const otherFkVal = otherRow[otherCol.field + '_fk'];
            if (String(otherFkVal) === String(item.id)) {
              const displayVal = otherCol.dbColumn ? otherRow[otherCol.dbColumn] : null;
              const otherRowLabel = (displayVal !== undefined && displayVal !== null && String(displayVal).trim() !== '')
                ? String(displayVal)
                : String(otherRow.clause || otherRow.title || otherRow.description || otherRow.details || otherRow.name || otherRow.field1 || otherRow.field2 || otherRow.id);
                
              links.push({
                docTitle: otherDocTitle,
                rowId: otherRow.id,
                rowLabel: otherRowLabel,
                relationType: 'referenced_by',
                relationLabel: isRtl ? `مورد ارجاع داده شده (ستون ${otherCol.label})` : `Referenced in (Col: ${otherCol.label})`
              });
            }
          });
        }
      });
    });

    // 3. PEER CONNECTIONS (Peers referencing the same row as this row)
    currentColumns.forEach(col => {
      if (col.type === 'db_lookup' && col.dbTable && col.dbColumn) {
        const fkVal = item[col.field + '_fk'];
        if (fkVal) {
          Object.keys(allDocs).forEach(otherDocTitle => {
            if (otherDocTitle === currentDocTitle) return;
            
            let otherCols: ColumnDefinition[] = [];
            try {
              const otherColsRaw = localStorage.getItem(`iatf_draft_cols_${otherDocTitle}`);
              if (otherColsRaw) {
                otherCols = JSON.parse(otherColsRaw);
              }
            } catch {}
            
            if (!Array.isArray(otherCols) || otherCols.length === 0) {
              const otherTpl = documentTemplates[otherDocTitle];
              if (otherTpl) {
                otherCols = getInitialColumns(otherTpl);
              }
            }
            
            otherCols.forEach(otherCol => {
              const isPeerRef = otherCol.type === 'db_lookup' && 
                                otherCol.dbTable === col.dbTable;
                                
              if (isPeerRef) {
                let otherDocRows = allDocs[otherDocTitle] || [];
                if (otherDocRows.length === 0) {
                  try {
                    const draftItemsRaw = localStorage.getItem(`iatf_draft_items_${otherDocTitle}`);
                    if (draftItemsRaw) otherDocRows = JSON.parse(draftItemsRaw);
                  } catch {}
                }
                
                otherDocRows.forEach((otherRow: any) => {
                  const otherFkVal = otherRow[otherCol.field + '_fk'];
                  if (otherFkVal && String(otherFkVal) === String(fkVal)) {
                    const alreadyExists = links.some(l => l.docTitle === otherDocTitle && l.rowId === otherRow.id);
                    if (!alreadyExists) {
                      const displayVal = otherCol.dbColumn ? otherRow[otherCol.dbColumn] : null;
                      const otherRowLabel = (displayVal !== undefined && displayVal !== null && String(displayVal).trim() !== '')
                        ? String(displayVal)
                        : String(otherRow.clause || otherRow.title || otherRow.description || otherRow.details || otherRow.name || otherRow.field1 || otherRow.field2 || otherRow.id);
                        
                      links.push({
                        docTitle: otherDocTitle,
                        rowId: otherRow.id,
                        rowLabel: otherRowLabel,
                        relationType: 'peer',
                        relationLabel: isRtl ? `هم‌بند متصل به مرجع مشترک` : `Connected via shared reference`
                      });
                    }
                  }
                });
              }
            });
          });
        }
      }
    });

    return links;
  };

