  // States to support declaring NCs directly from the visual Process Map nodes
  const [ncDeclaringNode, setNcDeclaringNode] = useState<any | null>(null);
  const [ncDescriptionMap, setNcDescriptionMap] = useState<string>('');
  const [ncReporterMap, setNcReporterMap] = useState<string>('');
  const [ncTargetDateMap, setNcTargetDateMap] = useState<string>('1405/03/30');
  const [ncResponseTypeMap, setNcResponseTypeMap] = useState<'CAPA' | 'INFO_ONLY'>('CAPA');
  const [showNcSuccessToastMap, setShowNcSuccessToastMap] = useState<string | null>(null);

  const handleDeclareNcFromMap = (e: React.FormEvent) => {
    e.preventDefault();
    if (!ncDeclaringNode || !ncDescriptionMap.trim()) return;

    try {
       const stored = localStorage.getItem('qmsdb_v3_nc_items');
       let list = [];
       if (stored) {
         try {
           const parsed = JSON.parse(stored);
           if (Array.isArray(parsed)) {
             list = parsed.filter(item => item && typeof item === 'object');
           }
         } catch (e) {
           console.error(e);
         }
       }

       const newNcId = `NC-2026-${(list.length + 1).toString().padStart(3, '0')}`;
       const newNc = {
         id: newNcId,
         clauseId: ncDeclaringNode.clauseId || '4.4',
         clauseNumber: ncDeclaringNode.clauseId || '4.4',
         clauseTitle: ncDeclaringNode.field1 || (lang === 'fa' ? 'فرآیند سازمان' : 'Org Process'),
         description: ncDescriptionMap.trim(),
         declaredAt: '1405/03/14',
         source: `${lang === 'fa' ? 'نقشه فرآیندهای تعاملی' : 'Interactive Process Map'} (${ncDeclaringNode.field1})`,
         reporter: ncReporterMap.trim() || (lang === 'fa' ? 'کارشناس فرآیند' : 'Process Analyst'),
         targetDate: ncTargetDateMap,
         status: 'NEW' as const,
         responseType: ncResponseTypeMap
       };

       const updated = [newNc, ...list];
       localStorage.setItem('qmsdb_v3_nc_items', JSON.stringify(updated));

       // Trigger standard QMS and App alarm sync
       window.dispatchEvent(new Event('qms_nc_updated'));

       setShowNcSuccessToastMap(newNcId);
       setNcDeclaringNode(null);
       setNcDescriptionMap('');
       setNcReporterMap('');
       setNcResponseTypeMap('CAPA');

       setTimeout(() => {
         setShowNcSuccessToastMap(null);
       }, 5000);
    } catch (err) {
      console.error('Failed to declare NC from process map:', err);
    }
  };

  // Calculate the spreadsheet grid values dynamically on any change using multi-pass evaluation
  const gridValues = useMemo(() => {
    const values: Record<string, any> = {};

    // First assign all raw cell values and formulas
    items.forEach((item, rowIndex) => {
      const rowNum = rowIndex + 1;
      
      // Pre-calculate standard read-only properties
      const finalScore = parseFloat(((item.weight || 0) * (item.rating || 0)).toFixed(2));
      const rpn = (item.severity || 1) * (item.occurrence || 1) * (item.detection || 1);
      const measuredErr = parseFloat(Math.abs(Number(item.readValue || 0) - Number(item.refValue || 0)).toFixed(4));
      
      columns.forEach((col, colIndex) => {
        const colLetter = colIndexToLetter(colIndex);
        const cellRef = `${colLetter}${rowNum}`;
        
        if (col.id === 'final_score') {
          values[cellRef] = finalScore;
        } else if (col.id === 'rpn') {
          values[cellRef] = rpn;
        } else if (col.id === 'measured_error') {
          values[cellRef] = measuredErr;
        } else {
          let rawVal = item[col.field];
          if (col.type === 'formula' && col.formula) {
            rawVal = col.formula.startsWith('=') ? col.formula : '=' + col.formula;
          }
          values[cellRef] = rawVal === undefined || rawVal === null ? '' : rawVal;
        }
      });
    });

    // Make 4 passes to resolve nested formula dependencies (chaining formulas)
    for (let pass = 0; pass < 4; pass++) {
      items.forEach((item, rowIndex) => {
        const rowNum = rowIndex + 1;
        columns.forEach((col, colIndex) => {
          const colLetter = colIndexToLetter(colIndex);
          const cellRef = `${colLetter}${rowNum}`;
          const rawVal = values[cellRef];
          if (typeof rawVal === 'string' && rawVal.startsWith('=')) {
            values[cellRef] = evaluateFormula(rawVal, rowIndex, columns, items, values);
          }
        });
      });
    }

    return values;
  }, [items, columns]);

  // Dynamic spreadsheet calculation engine for Process Location (Context Rows Table A)
  const contextGridValues = useMemo(() => {
    const values: Record<string, any> = {};
    const currentContextRows = items.filter(i => i.type === 'context');
    
    currentContextRows.forEach((item, rowIndex) => {
      const rowNum = rowIndex + 1;
      const cols = ['field1', 'field2', 'field3', 'field4', 'field5'];
      cols.forEach((field, colIdx) => {
        const colLetter = colIndexToLetter(colIdx);
        const cellRef = `${colLetter}${rowNum}`;
        const dbLinkName = `${field}_db_link`;
        let val = item[field];
        if (item[dbLinkName]) {
          val = resolveCellDbLink(item[dbLinkName], lang === 'fa');
        }
        values[cellRef] = val === undefined || val === null ? '' : val;
      });
    });

    const cols = ['field1', 'field2', 'field3', 'field4', 'field5'];
    const mockCols = cols.map((field, colIdx) => ({
      id: field,
      field: field,
      label: field,
      type: 'textarea' as const
    }));

    for (let pass = 0; pass < 4; pass++) {
      currentContextRows.forEach((item, rowIndex) => {
        const rowNum = rowIndex + 1;
        cols.forEach((field, colIdx) => {
          const colLetter = colIndexToLetter(colIdx);
          const cellRef = `${colLetter}${rowNum}`;
          const rawVal = values[cellRef];
          if (typeof rawVal === 'string' && rawVal.startsWith('=')) {
            values[cellRef] = evaluateFormula(rawVal, rowIndex, mockCols, currentContextRows, values);
          }
        });
      });
    }

    return values;
  }, [items, lang]);

  // Dynamic spreadsheet calculation engine for Process Specific FMEA (Risk Table B)
  const riskGridValues = useMemo(() => {
    const values: Record<string, any> = {};
    const currentRiskRows = items.filter(i => i.type === 'risk_and_opp');

    const riskFields = [
      { field: 'field1', type: 'textarea' }, // A (Risk)
      { field: 'numeric1', type: 'number' },  // B (O1)
      { field: 'numeric2', type: 'number' },  // C (S1)
      { field: 'numeric3', type: 'number' },  // D (Score1)
      { field: 'field2', type: 'textarea' }, // E (Action)
      { field: 'numeric4', type: 'number' },  // F (O2)
      { field: 'numeric5', type: 'number' },  // G (S2)
      { field: 'numeric6', type: 'number' },  // H (Score2)
      { field: 'field3', type: 'textarea' }, // I (Opportunity)
      { field: 'field4', type: 'textarea' }, // J (Opportunity Action)
    ];

    currentRiskRows.forEach((item, rowIndex) => {
      const rowNum = rowIndex + 1;
      riskFields.forEach((itemField, colIdx) => {
        const colLetter = colIndexToLetter(colIdx);
        const cellRef = `${colLetter}${rowNum}`;
        const field = itemField.field;
        const dbLinkName = `${field}_db_link`;
        let val = item[field];
        if (item[dbLinkName]) {
          val = resolveCellDbLink(item[dbLinkName], lang === 'fa');
        } else {
          if (field === 'numeric3' && (val === undefined || val === null || val === '')) {
            val = Number(item.numeric1 || 1) * Number(item.numeric2 || 1);
          } else if (field === 'numeric6' && (val === undefined || val === null || val === '')) {
            val = Number(item.numeric4 || 1) * Number(item.numeric5 || 1);
          }
        }
        values[cellRef] = val === undefined || val === null ? '' : val;
      });
    });

    const mockCols = riskFields.map((itemField, colIdx) => ({
      id: itemField.field,
      field: itemField.field,
      label: itemField.field,
      type: itemField.type as any
    }));

    for (let pass = 0; pass < 4; pass++) {
      currentRiskRows.forEach((item, rowIndex) => {
        const rowNum = rowIndex + 1;
        riskFields.forEach((itemField, colIdx) => {
          const colLetter = colIndexToLetter(colIdx);
          const cellRef = `${colLetter}${rowNum}`;
          const rawVal = values[cellRef];
          if (typeof rawVal === 'string' && rawVal.startsWith('=')) {
            values[cellRef] = evaluateFormula(rawVal, rowIndex, mockCols, currentRiskRows, values);
          }
        });
      });
    }

    return values;
  }, [items, lang]);

  // Load manual clause mappings on mount or open
  useEffect(() => {
    if (isOpen) {
      try {
        const dbMappings = QmsDatabase.selectAll(QmsDatabase.TABLES.PROCESS_MAPPINGS);
        if (dbMappings && Object.keys(dbMappings).length > 0) {
          setManualClauseMapping(dbMappings);
        } else {
          const raw = localStorage.getItem('iatf_manual_clause_mappings');
          if (raw) {
            setManualClauseMapping(JSON.parse(raw));
          } else {
            setManualClauseMapping({});
          }
        }
      } catch (e) {
        console.warn('Failed loading manual clause mappings:', e);
      }
    }
  }, [isOpen]);

  // Precompute flattened clauses for selection list
  const allFlattenedClauses = useMemo(() => {
    return flattenIatfClauses(iatfData);
  }, []);

  // Filter clauses reactively based on search query
  const flattenedAndFilteredClauses = useMemo(() => {
    const q = clauseSearch.trim().toLowerCase();
    if (!q) return allFlattenedClauses;
    return allFlattenedClauses.filter(c => 
      c.id.toLowerCase().includes(q) || 
      c.title.toLowerCase().includes(q) || 
      (c.text && c.text.toLowerCase().includes(q))
    );
  }, [allFlattenedClauses, clauseSearch]);

  // Sync selectedClauseIds with custom or automatic mappings on item selection
  useEffect(() => {
    if (activeManualClauseItem) {
      const { itemId, processName } = activeManualClauseItem;
      const customOnes = manualClauseMapping[itemId] || manualClauseMapping[processName] || [];
      
      if (customOnes.length > 0) {
        setSelectedClauseIds(customOnes);
      } else {
        const item = items.find(it => it.id === itemId);
        if (item) {
          const procClauseExpr = item.clauseId || '4.4';
          const autoMatched = allFlattenedClauses
            .filter(c => isClauseAssociated(c.id, procClauseExpr))
            .map(c => c.id);
          setSelectedClauseIds(autoMatched);
        } else {
          setSelectedClauseIds([]);
        }
      }
      setClauseSearch('');
    }
  }, [activeManualClauseItem, manualClauseMapping, items, allFlattenedClauses]);

  // Update turtle visual connectors on layout change or resize
  useEffect(() => {
    if (template.smartType !== 'TURTLE' || turtleMode !== 'visual' || !items[selectedTurtleIndex]) return;

    const updateTurtleLines = () => {
      const container = turtleContainerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const centerEl = document.getElementById('turtle-center-circle');
      if (!centerEl) return;

      const centerRect = centerEl.getBoundingClientRect();
      const cx = centerRect.left - rect.left + centerRect.width / 2;
      const cy = centerRect.top - rect.top + centerRect.height / 2;

      const targets = [
        'turtle-card-top-left',
        'turtle-card-middle-left',
        'turtle-card-bottom-left',
        'turtle-card-top-right',
        'turtle-card-middle-right',
        'turtle-card-bottom-right'
      ];

      const newCoords = targets.map(id => {
        const el = document.getElementById(id);
        if (!el) return null;
        const elRect = el.getBoundingClientRect();
        const tx = elRect.left - rect.left + elRect.width / 2;
        const ty = elRect.top - rect.top + elRect.height / 2;
        return { x1: cx, y1: cy, x2: tx, y2: ty };
      }).filter(Boolean) as { x1: number; y1: number; x2: number; y2: number }[];

      setTurtleCoords(newCoords);
    };

    updateTurtleLines();
    const timer = setTimeout(updateTurtleLines, 300);

    window.addEventListener('resize', updateTurtleLines);
    
    let observer: ResizeObserver | null = null;
    if (typeof ResizeObserver !== 'undefined' && turtleContainerRef.current) {
      observer = new ResizeObserver(updateTurtleLines);
      observer.observe(turtleContainerRef.current);
    }

    return () => {
      clearTimeout(timer);
      window.removeEventListener('resize', updateTurtleLines);
      if (observer) {
        observer.disconnect();
      }
    };
  }, [items, selectedTurtleIndex, turtleMode, template.smartType]);

  const [editingKpiId, setEditingKpiId] = useState<string | null>(null);
  const [editingKpiTitle, setEditingKpiTitle] = useState('');
  const [editingKpiTarget, setEditingKpiTarget] = useState<number>(100);
  const [editingKpiActual, setEditingKpiActual] = useState<number>(100);
  const [editingKpiUnit, setEditingKpiUnit] = useState('%');
  const [docCode, setDocCode] = useState('');
  const [docReleaseDate, setDocReleaseDate] = useState('');
  const [docType, setDocType] = useState<'manual' | 'procedure' | 'work_instruction' | 'form' | 'list_matrix' | 'record'>('procedure');
  const [docTitle, setDocTitle] = useState(template.title);

  // Flatten standard clauses and filter into allocated vs unallocated
  const { allocatedClauses, unallocatedClauses } = useMemo(() => {
    const allClauses = flattenIatfClauses(iatfData);
    const allocated: { clause: typeof iatfData[0]; processes: string[] }[] = [];
    const unallocated: typeof iatfData[0][] = [];

    // Safe retrieve of turtle processes from Storage OR local DB
    let turtleItems: DocItem[] = [];
    try {
      const dbDocs = QmsDatabase.selectAll('documents_table') || {};
      const turtleDoc = dbDocs['شناسنامه فرآیندها (Process Cards - Turtle)'] || 
                        dbDocs['شناسنامه فرآیندها'] || 
                        dbDocs['لاک‌پشتی فرایندها (Turtle Diagrams)'];
      if (Array.isArray(turtleDoc)) {
        turtleItems = turtleDoc;
      }
    } catch {}

    if (turtleItems.length === 0) {
      const sourceKeys = [
        'iatf_draft_items_شناسنامه فرآیندها (Process Cards - Turtle)',
        'iatf_draft_items_شناسنامه فرآیندها',
        'iatf_draft_items_لاک‌پشتی فرایندها (Turtle Diagrams)'
      ];
      for (const key of sourceKeys) {
        const raw = localStorage.getItem(key);
        if (raw) {
          try {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed) && parsed.length > 0) {
              turtleItems = parsed;
              break;
            }
          } catch {}
        }
      }
    }

    allClauses.forEach(clause => {
      const matchingProcs = turtleItems.filter(proc => {
        const procClauseExpr = proc.clauseId || '4.4';
        return isClauseAssociated(clause.id, procClauseExpr);
      });

      if (matchingProcs.length > 0) {
        allocated.push({
          clause,
          processes: matchingProcs.map(p => p.field1 || 'فرآیند بدون نام')
        });
      } else {
        unallocated.push(clause);
      }
    });

    return { allocatedClauses: allocated, unallocatedClauses: unallocated };
  }, [items]);

  const filteredActiveClauses = useMemo(() => {
    const query = matrixSearchText.trim().toLowerCase();
    if (!query) {
      return matrixTab === 'allocated' ? allocatedClauses : unallocatedClauses;
    }
    if (matrixTab === 'allocated') {
      return allocatedClauses.filter(item => 
        item.clause.id.toLowerCase().includes(query) ||
        item.clause.title.toLowerCase().includes(query) ||
        item.clause.text.toLowerCase().includes(query) ||
        item.processes.some((p: string) => p.toLowerCase().includes(query))
      );
    } else {
      return unallocatedClauses.filter(clause => 
        clause.id.toLowerCase().includes(query) ||
        clause.title.toLowerCase().includes(query) ||
        clause.text.toLowerCase().includes(query)
      );
    }
  }, [matrixTab, matrixSearchText, allocatedClauses, unallocatedClauses]);

  // Initialize and load dynamic QMS metadata profile
  useEffect(() => {
    if (isOpen) {
      const cleanDocName = template.title.replace(/\s*\(ارجاع به بند.*\)/, '').trim();
      setDocTitle(cleanDocName);
      
      if (requireMetadata) {
        const dbSaved = QmsDatabase.selectRow<any>('document_control_table', cleanDocName);
        if (dbSaved) {
          setDocCode(dbSaved.code || '');
          setDocReleaseDate(dbSaved.releaseDate || '1405/03/01');
          setDocType(dbSaved.docType || 'procedure');
        } else {
          let initialType: 'manual' | 'procedure' | 'work_instruction' | 'form' | 'list_matrix' | 'record' = 'procedure';
          const normTitle = cleanDocName.toLowerCase();
          if (normTitle.includes('روش اجرایی') || normTitle.includes('رویه')) initialType = 'procedure';
          else if (normTitle.includes('دستورالعمل')) initialType = 'work_instruction';
          else if (normTitle.includes('فرم')) initialType = 'form';
          else if (normTitle.includes('لیست') || normTitle.includes('ماتریس')) initialType = 'list_matrix';
          else if (normTitle.includes('نظام‌نامه')) initialType = 'manual';
          else initialType = 'record';

          let prefix = 'QMS-REC';
          if (initialType === 'procedure') prefix = 'QMS-PR';
          else if (initialType === 'work_instruction') prefix = 'QMS-WI';
          else if (initialType === 'form') prefix = 'QMS-FM';
          else if (initialType === 'list_matrix') prefix = 'QMS-LS';
          else if (initialType === 'manual') prefix = 'QMS-QM';

          const baseHash = Math.abs(cleanDocName.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0));
          const allRowsMap = QmsDatabase.selectAll<any>('document_control_table') || {};
          const allDocs = Object.values(allRowsMap);
          
          let finalCode = '';
          for (let seqOffset = 0; seqOffset < 200; seqOffset++) {
            const sequenceNum = ((baseHash + seqOffset) % 99 + 1).toString().padStart(2, '0');
            const testCode = `${prefix}-7_5-${sequenceNum}`;
            
            const isOccupied = allDocs.some((d: any) => 
              d.code?.trim().toLowerCase() === testCode.toLowerCase()
            );
            
            if (!isOccupied) {
              finalCode = testCode;
              break;
            }
          }
          
          if (!finalCode) {
            finalCode = `${prefix}-7_5-${(baseHash % 99 + 1).toString().padStart(2, '0')}`;
          }

          setDocCode(finalCode);
          setDocReleaseDate('1405/03/01');
          setDocType(initialType);
          
          QmsDatabase.writeRow('document_control_table', cleanDocName, {
            id: cleanDocName,
            code: finalCode,
            revision: '00',
            releaseDate: '1405/03/01',
            preparedBy: isRtl ? 'تضمین کیفیت' : 'QA',
            approvedBy: isRtl ? 'مدیر ارشد مهندسی' : 'QMS Management Rep',
            status: 'approved',
            docType: initialType,
            notes: isRtl ? 'کدگذاری خودکار' : 'Auto-configured code'
          });
        }
      }
    }
  }, [isOpen, template.title, requireMetadata]);

  const handleDocTypeChange = (newType: 'manual' | 'procedure' | 'work_instruction' | 'form' | 'list_matrix' | 'record') => {
    setDocType(newType);
    
    // Auto-generate fresh unique code
    const originalTitle = template.title.replace(/\s*\(ارجاع به بند.*\)/, '').trim();
    const cleanDocName = docTitle.trim() || originalTitle;
    
    let prefix = 'QMS-REC';
    if (newType === 'procedure') prefix = 'QMS-PR';
    else if (newType === 'work_instruction') prefix = 'QMS-WI';
    else if (newType === 'form') prefix = 'QMS-FM';
    else if (newType === 'list_matrix') prefix = 'QMS-LS';
    else if (newType === 'manual') prefix = 'QMS-QM';

    const baseHash = Math.abs(cleanDocName.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0));
    const allRowsMap = QmsDatabase.selectAll<any>('document_control_table') || {};
    const allDocs = Object.values(allRowsMap);
    
    let finalCode = '';
    for (let seqOffset = 0; seqOffset < 200; seqOffset++) {
      const sequenceNum = ((baseHash + seqOffset) % 99 + 1).toString().padStart(2, '0');
      const testCode = `${prefix}-7_5-${sequenceNum}`;
      
      // Check if testCode is already used by some other document
      const isOccupied = allDocs.some((d: any) => 
        d.code?.trim().toLowerCase() === testCode.toLowerCase() &&
        d.id?.trim().toLowerCase() !== originalTitle.toLowerCase() &&
        d.id?.trim().toLowerCase() !== cleanDocName.toLowerCase()
      );
      
      if (!isOccupied) {
        finalCode = testCode;
        break;
      }
    }
    
    if (!finalCode) {
      finalCode = `${prefix}-7_5-${(baseHash % 99 + 1).toString().padStart(2, '0')}`;
    }
    
    setDocCode(finalCode);
  };

  const [colWidths, setColWidths] = useState<Record<string, number>>(() => {
    try {
      const saved = localStorage.getItem(`iatf_draft_col_widths_${template.title}`);
      return saved ? JSON.parse(saved) : {};
    } catch {
      return {};
    }
  });

  useEffect(() => {
    if (isOpen && Object.keys(colWidths).length > 0) {
      localStorage.setItem(`iatf_draft_col_widths_${template.title}`, JSON.stringify(colWidths));
    }
  }, [colWidths, template.title, isOpen]);

  const handleResizeStart = (colId: string, e: React.MouseEvent) => {
    e.preventDefault();
    const startX = e.clientX;
    const initialWidth = colWidths[colId] || 180;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      const delta = moveEvent.clientX - startX;
      const adjust = isRtl ? -delta : delta;
      const newWidth = Math.max(90, initialWidth + adjust);
      setColWidths(prev => ({
        ...prev,
        [colId]: newWidth
      }));
    };

    const handleMouseUp = () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  const autofitSingleColumn = (colId: string) => {
    const colDef = columns.find(c => c.id === colId);
    if (!colDef) return;

    // Start with column header length
    let maxChars = colDef.label ? colDef.label.length : 10;

    // Scan values in rows
    items.forEach(item => {
      const val = item[colDef.field] !== undefined ? item[colDef.field] : item[colId];
      if (val !== undefined && val !== null) {
        const valStr = String(val);
        let visualLen = 0;
        for (let i = 0; i < valStr.length; i++) {
          const code = valStr.charCodeAt(i);
          visualLen += code > 128 ? 1.45 : 1; // wider multiplier for RTL/Persian chars
        }
        if (visualLen > maxChars) {
          maxChars = visualLen;
        }
      }
    });

    const fittedWidth = Math.min(Math.max(Math.ceil(maxChars * 8.5) + 40, 110), 550);
    setColWidths(prev => ({
      ...prev,
      [colId]: fittedWidth
    }));
  };

  const autofitAllColumns = () => {
    const nextWidths = { ...colWidths };
    columns.forEach(colDef => {
      const colId = colDef.id;
      let maxChars = colDef.label ? colDef.label.length : 10;
      items.forEach(item => {
        const val = item[colDef.field] !== undefined ? item[colDef.field] : item[colId];
        if (val !== undefined && val !== null) {
          const valStr = String(val);
          let visualLen = 0;
          for (let i = 0; i < valStr.length; i++) {
            const code = valStr.charCodeAt(i);
            visualLen += code > 128 ? 1.45 : 1;
          }
          if (visualLen > maxChars) {
            maxChars = visualLen;
          }
        }
      });
      const fittedWidth = Math.min(Math.max(Math.ceil(maxChars * 8.5) + 40, 110), 550);
      nextWidths[colId] = fittedWidth;
    });
    setColWidths(nextWidths);
  };

  const t = uiTranslations[lang];
  const isProcessMap = template.title.includes('Process Map') || template.title.includes('نقشه فرایند') || template.title.includes('نقشه فرآیند');

  const associatedClauses = useMemo(() => {
    const list: string[] = [];
    if (template.clauseId) {
      list.push(template.clauseId);
    }
    
    // Reverse lookup in standard tree data
    try {
      const flat = flattenIatfClauses(iatfData);
      const cleanTitle = template.title.replace(/\s*\(ارجاع به بند.*\)/, '').replace(/\s*\(Process-Requirements Matrix\)/, '').replace(/\s*\(Process Cards - Turtle\)/, '').trim();
      
      flat.forEach(c => {
        if (c.documents && Array.isArray(c.documents)) {
          const match = c.documents.some(d => {
            const cleanD = d.replace(/\s*\(ارجاع به بند.*\)/, '').replace(/\s*\(Process-Requirements Matrix\)/, '').replace(/\s*\(Process Cards - Turtle\)/, '').trim();
            return cleanD === cleanTitle || cleanTitle.includes(cleanD) || cleanD.includes(cleanTitle);
          });
          if (match && !list.includes(c.id)) {
            list.push(c.id);
          }
        }
      });
    } catch (e) {
      console.warn('Error in reverse clause lookup:', e);
    }
    
    return list;
  }, [template.title, template.clauseId]);

  const isDependentDoc = template.smartType === 'INTERNAL_AUDIT' || template.smartType === 'PROCESS_MATRIX';

  // Load Turtle processes defined under standard turtle document templates
  const turtleProcesses = useMemo(() => {
    let list: string[] = [];
    try {
      // Direct query to the QmsDatabase for the process card document defined under بند 4.4
      const docTitles = [
        'شناسنامه فرآیندها (Process Cards - Turtle)',
        'شناسنامه فرآیندها',
        'لاک‌پشتی فرایندها (Turtle Diagrams)'
      ];
      for (const title of docTitles) {
        const rows = QmsDatabase.selectRow<any[]>('documents_table', title);
        if (Array.isArray(rows) && rows.length > 0) {
          list = rows.map(p => p.field1 || '').filter(Boolean);
          if (list.length > 0) break;
        }
      }
    } catch (e) {
      console.warn('QmsDatabase selectRow failed for شناسنامه فرآیندها:', e);
    }

    if (list.length === 0) {
      try {
        const dbDocs = QmsDatabase.selectAll('documents_table') || {};
        const turtleDoc = dbDocs['شناسنامه فرآیندها (Process Cards - Turtle)'] || 
                          dbDocs['شناسنامه فرآیندها'] || 
                          dbDocs['لاک‌پشتی فرایندها (Turtle Diagrams)'];
        if (Array.isArray(turtleDoc)) {
          list = turtleDoc.map(p => p.field1 || '').filter(Boolean);
        }
      } catch {}
    }

    if (list.length === 0) {
      const sourceKeys = [
        'iatf_draft_items_شناسنامه فرآیندها (Process Cards - Turtle)',
        'iatf_draft_items_شناسنامه فرآیندها',
        'iatf_draft_items_لاک‌پشتی فرایندها (Turtle Diagrams)'
      ];
      for (const key of sourceKeys) {
        const raw = localStorage.getItem(key);
        if (raw) {
          try {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed) && parsed.length > 0) {
              list = parsed.map(p => p.field1 || '').filter(Boolean);
              break;
            }
          } catch {}
        }
      }
    }
    // Strict Database Relation: Ensure 100% uniqueness of processes to prevent any duplicate rows/columns mapping errors
    return Array.from(new Set(list.map(name => name.trim()).filter(Boolean)));
  }, []);

  // States and Handlers for the Unified Risk Management Center (smartType: RISK_CENTER)
  const [activeRiskTab, setActiveRiskTab] = useState<'process' | 'product' | 'supplier' | 'project' | 'emergency'>(() => {
    const parentId = template.clauseId || '';
    if (parentId.startsWith('8.1')) return 'project';
    if (parentId.startsWith('8.3')) return 'product';
    if (parentId.startsWith('8.4')) return 'supplier';
    if (parentId.startsWith('6.1.2.3')) return 'emergency';
    return 'process';
  });

  const [selectedRiskClause, setSelectedRiskClause] = useState<string>('all');
  const [processFilter, setProcessFilter] = useState<string | null>(null);
  const [isIntegrityPanelOpen, setIsIntegrityPanelOpen] = useState<boolean>(false);
  const [selectedDbTable, setSelectedDbTable] = useState<string>('documents_table');
  const [dbSearchQuery, setDbSearchQuery] = useState<string>('');

  // States for 'RISK_MANAGEMENT' (Clause 6.1)
  const [selectedRiskProcess, setSelectedRiskProcess] = useState<string>('');
  const [generatingRisksFor, setGeneratingRisksFor] = useState<string>('');
  const [riskMatrixDim, setRiskMatrixDim] = useState<number>(5);
  const [riskMatrixLimit, setRiskMatrixLimit] = useState<number>(10);
  const [riskActiveViewTab, setRiskActiveViewTab] = useState<'processes' | 'matrix' | 'lessons' | 'risk_clause_matrix' | 'strategic_risks'>(initialRiskActiveViewTab || 'processes');

  // States for Strategic Risks database connections (Request 2)
  const [strategicDbConfig, setStrategicDbConfig] = useState<Record<string, { dbTable?: string; dbColumn?: string }>>(() => {
    try {
      const saved = localStorage.getItem('iatf_strategic_db_config');
      return saved ? JSON.parse(saved) : {};
    } catch {
      return {};
    }
  });
  const [openStrategicDbColId, setOpenStrategicDbColId] = useState<string | null>(null);
  const [openStrategicDbTableSelectColId, setOpenStrategicDbTableSelectColId] = useState<string | null>(null);
  const [strategicDbTableSearch, setStrategicDbTableSearch] = useState<string>('');

  const [strategicCoords, setStrategicCoords] = useState<{ top: number; left: number } | null>(null);

  const updateStrategicDbConfig = (colId: string, updates: Partial<{ dbTable: string; dbColumn: string }>) => {
    setStrategicDbConfig(prev => {
      const updated = {
        ...prev,
        [colId]: {
          ...(prev[colId] || {}),
          ...updates
        }
      };
      localStorage.setItem('iatf_strategic_db_config', JSON.stringify(updated));
      return updated;
    });
  };

  const toggleStrategicDbMenu = (field: string, event: React.MouseEvent<HTMLButtonElement>) => {
    if (openStrategicDbColId === field) {
      setOpenStrategicDbColId(null);
    } else {
      const rect = event.currentTarget.getBoundingClientRect();
      const menuWidth = 260;
      const menuHeight = 280; // approximate menu height
      const screenWidth = window.innerWidth;
      const screenHeight = window.innerHeight;
      
      let leftPos = isRtl ? (rect.right - menuWidth) : rect.left;
      if (leftPos < 12) leftPos = 12;
      if (leftPos + menuWidth > screenWidth - 12) {
        leftPos = screenWidth - menuWidth - 12;
      }
      
      let topPos = rect.bottom + 6;
      // Vertically flip to render ABOVE if not enough space below
      if (rect.bottom + menuHeight > screenHeight - 12 && rect.top - menuHeight > 12) {
        topPos = rect.top - menuHeight - 6;
      }
      
      setStrategicCoords({ top: topPos, left: leftPos });
      setOpenStrategicDbColId(field);
    }
  };

  const getSharedColumnFriendlyName = (colName: string, dbTable: string) => {
    if (dbTable && dbTable.startsWith('doc_')) {
      const targetDocName = dbTable.substring(4);
      try {
        let savedColsRaw = localStorage.getItem(`iatf_draft_cols_${targetDocName}`);
        if (!savedColsRaw) {
          const tpl = documentTemplates[targetDocName];
          if (tpl?.smartType === 'SWOT') {
            savedColsRaw = localStorage.getItem('iatf_draft_cols_ماتریس SWOT سازمان') || localStorage.getItem('iatf_draft_cols_ماتریس SWOT (نقاط قوت، ضعف، فرصت‌ها و تهدیدها)');
          }
        }
        if (savedColsRaw) {
          const savedCols = JSON.parse(savedColsRaw);
          if (Array.isArray(savedCols)) {
            const colDef = savedCols.find(co => co.field === colName || co.id === colName);
            if (colDef && colDef.label && colDef.label.trim() !== '') {
              return `${colDef.label} (${colName})`;
            }
          }
        }
        
        const tpl = documentTemplates[targetDocName];
        if (tpl) {
          const initialCols = getInitialColumns(tpl);
          const colDef = initialCols.find(co => co.field === colName || co.id === colName);
          if (colDef && colDef.label && colDef.label.trim() !== '') {
            return `${colDef.label} (${colName})`;
          }
        }
      } catch (e) {
        // ignore
      }
      return colName;
    }
    
    const translations: Record<string, string> = {
      code: isRtl ? 'کد سند' : 'Code',
      revision: isRtl ? 'نسخه بازنگری' : 'Revision',
      preparedBy: isRtl ? 'تهیه‌کننده' : 'Prepared By',
      approvedBy: isRtl ? 'تاییدکننده/ناشر' : 'Approved By',
      lifecycle_status: isRtl ? 'وضعیت چرخه سند' : 'Lifecycle Status',
      type: isRtl ? 'نوع شاخص/عامل' : 'Type',
      titleFa: isRtl ? 'عنوان فارسی' : 'Title (Fa)',
      titleEn: isRtl ? 'عنوان انگلیسی' : 'Title (En)',
      target: isRtl ? 'هدف گذاری' : 'Target',
      unit: isRtl ? 'واحد سنجش' : 'Unit',
      rowCount: isRtl ? 'تعداد ردیف‌ها' : 'Row Count',
      lastUpdatedTime: isRtl ? 'زمان بروزرسانی' : 'Last Updated',
      documents_list: isRtl ? 'لیست مستندات' : 'Documents List',
      id: isRtl ? 'شناسه (ID)' : 'ID',
      title: isRtl ? 'عنوان / شرح عامل' : 'Title',
      description: isRtl ? 'شرح / توضیحات' : 'Description',
      isActive: isRtl ? 'وضعیت فعال بودن' : 'Is Active',
      clauseNumber: isRtl ? 'شماره بند' : 'Clause Number',
      lastReview: isRtl ? 'آخرین ممیزی' : 'Last Review',
      clauseId: isRtl ? 'کد بند استاندارد' : 'Clause ID',
      clauseTitle: isRtl ? 'عنوان بند استاندارد' : 'Clause Title',
      declaredAt: isRtl ? 'تاریخ صدور / اعلام' : 'Declared At',
      source: isRtl ? 'منبع عیب' : 'Source',
      reporter: isRtl ? 'گزارش‌دهنده' : 'Reporter',
      targetDate: isRtl ? 'تاریخ اقدام (سررسید)' : 'Target Date',
      status: isRtl ? 'وضعیت پرونده' : 'Status',
      delayReason: isRtl ? 'علت انحراف/تاخیر' : 'Delay Reason',
      evaluation: isRtl ? 'شرح ارزیابی' : 'Evaluation Description',
      weight: isRtl ? 'وزن اهمیت عامل' : 'Weight',
      rating: isRtl ? 'رتبه تأثیر (Rating)' : 'Rating',
      score: isRtl ? 'نمره نهایی (Score)' : 'Final Score',
      desc: isRtl ? 'توصیف تفصیلی عامل' : 'Description Details',
      clause: isRtl ? 'کد بند انتسابی' : 'Associated Clause',
      impactCustomer: isRtl ? 'تاثیر روی مشتری (Severity)' : 'Customer Impact',
      impactQuality: isRtl ? 'تاثیر روی کیفیت' : 'Quality Impact',
      impactProcess: isRtl ? 'تاثیر روی فرآیند' : 'Process Impact',
      impactGoals: isRtl ? 'تاثیر روی اهداف' : 'Goals Impact',
      impactLegal: isRtl ? 'تاثیر قانونی و الزامات' : 'Legal Impact',
      probability: isRtl ? 'احتمال وقوع (O)' : 'Probability',
      nature: isRtl ? 'ماهیت (ریسک/فرصت)' : 'Nature'
    };
    return translations[colName] || colName;
  };

  const renderStrategicHeaderDbMenu = (field: string, label: string) => {
    const config = strategicDbConfig[field] || {};
    const isOpen = openStrategicDbColId === field;
    if (!isOpen || !strategicCoords) return null;

    const virtualCol: ColumnDefinition = {
      id: field,
      label: label,
      field: field,
      type: 'db_lookup',
      dbTable: config.dbTable,
      dbColumn: config.dbColumn,
    };

    return createPortal(
      <div 
        style={{
          position: 'fixed',
          top: strategicCoords.top,
          left: strategicCoords.left,
          width: '260px'
        }}
        className="bg-[#0A0A0C] border border-[#252528] rounded-lg shadow-2xl p-2.5 text-[9px] text-[#A0A0AA] flex flex-col gap-2 text-[#FAFAFA] text-right z-[99999] select-none font-sans" 
        dir="rtl" 
        onClick={e => e.stopPropagation()}
      >
        <div className="flex items-center justify-between border-b border-white/5 pb-1.5 mb-0.5">
          <div className="flex items-center gap-1 text-amber-500 font-bold">
            <Database size={10} />
            <span>{isRtl ? 'اتصال ستون به دیتابیس QMS' : 'Standard QMS DB Link'}</span>
          </div>
          <button 
            type="button" 
            onClick={() => setOpenStrategicDbColId(null)}
            className="text-zinc-500 hover:text-white text-[10px]"
          >
            ✕
          </button>
        </div>

        {/* Database Table Select */}
        <div className="flex flex-col gap-1 relative">
          <span className="text-[#65656F] text-[8px] font-bold">{isRtl ? 'جدول یا سند هدف:' : 'Target Database Table:'}</span>
          
          <div className="relative w-full">
            <button
              type="button"
              onClick={() => {
                setOpenStrategicDbTableSelectColId(openStrategicDbTableSelectColId === `strategic_${field}` ? null : `strategic_${field}`);
              }}
              className="bg-[#1A1A1C] border border-[#232326] hover:border-[#3A3A3F] text-[9px] text-white p-1.5 rounded outline-none w-full text-right flex items-center justify-between cursor-pointer transition-all"
            >
              <span className="truncate">
                {(() => {
                  const allTables = [
                    { id: 'document_control_table', label: isRtl ? '📝 کنترل مستندات (ISO9001)' : '📝 Doc Control' },
                    { id: 'indicators_table', label: isRtl ? '📊 شاخص‌های کلیدی (KPI)' : '📊 KPI Indicators' },
                    { id: 'documents_table', label: isRtl ? '📂 مستندات و فرم‌ها (QMS)' : '📂 Custom Docs' },
                    { id: 'clause_links_table', label: isRtl ? '📚 لینک‌های بند سازمانی' : '📚 Clause Links' },
                    { id: 'strategic_evaluations_table', label: isRtl ? '🎯 ارزیابی استراتژیک (SWOT/PESTEL)' : '🎯 Strategic SWOT/PEST' },
                    { id: 'strategic_items_table', label: isRtl ? '🎯 کارت‌های برنامه‌ریزی استراتژیک' : '🎯 Strategic Cards' },
                    { id: 'nc_items_table', label: isRtl ? '🛠️ اقدامات اصلاحی و عدم انطباق‌ها (CAPA)' : '🛠️ CAPA Corrective Actions' },
                    { id: 'records_table', label: isRtl ? '⚙️ آرشیو سوابق و مستندات' : '⚙️ Archives & Records' },
                    { id: 'csr_mappings_table', label: isRtl ? '🗂️ مقایسه الزامات خاص مشتریان (CSR)' : '🗂️ Customer Specific Requirements (CSR)' },
                    { id: 'process_mappings_table', label: isRtl ? '🗺️ نقشه فرآیندهای سازمانی' : '🗺️ Process Mapping Matrix' },
                    { id: 'kpi_vars_table', label: isRtl ? '📈 متغیرهای محاسباتی آمارها' : '📈 KPI Variables' },
                    { id: 'strategic_threshold_matrix_table', label: isRtl ? '⚙️ تنظیمات آستانه ماتریس ریسک' : '⚙️ Strategic Threshold Matrix' }
                  ];
                  try {
                    const docsGroup = QmsDatabase.selectAll('documents_table') || {};
                    Object.keys(docsGroup).forEach(title => {
                      allTables.push({
                        id: `doc_${title}`,
                        label: isRtl ? `📋 سند: ${title}` : `📋 Document: ${title}`
                      });
                    });
                  } catch (e) {}

                  const selected = allTables.find(t => t.id === config.dbTable);
                  if (selected) {
                    let searchName = selected.id;
                    if (selected.id.startsWith('doc_')) {
                      searchName = selected.id.substring(4);
                    } else {
                      if (selected.id === 'document_control_table') searchName = 'کنترل مستندات';
                      else if (selected.id === 'indicators_table') searchName = 'شاخص‌های کلیدی عملکرد (KPI)';
                      else if (selected.id === 'documents_table') searchName = 'مستندات و فرم‌ها';
                      else if (selected.id === 'clause_links_table') searchName = 'لینک‌های بند سازمانی';
                      else if (selected.id === 'strategic_evaluations_table') searchName = 'ارزیابی استراتژیک';
                      else if (selected.id === 'nc_items_table') searchName = 'اقدامات اصلاحی و عدم انطباق‌ها';
                      else if (selected.id === 'process_mappings_table') searchName = 'نقشه فرآیندهای سازمان';
                      else if (selected.id === 'records_table') searchName = 'آرشیو سوابق و مستندات';
                      else if (selected.id === 'csr_mappings_table') searchName = 'مقایسه الزامات خاص مشتریان (CSR)';
                      else if (selected.id === 'kpi_vars_table') searchName = 'متغیرهای محاسباتی آمارها';
                      else if (selected.id === 'strategic_threshold_matrix_table') searchName = 'تنظیمات آستانه ماتریس ریسک';
                    }
                    const clauseNo = getClauseNumberForDocument(searchName);
                    const clauseSuffix = clauseNo ? ` (بند ${clauseNo})` : '';
                    return `${selected.label}${clauseSuffix}`;
                  }
                  return isRtl ? '-- انتخاب جدول یا سند مرجع --' : '-- Choose Database Table --';
                })()}
              </span>
              <ChevronDown size={10} className="text-[#65656F]" />
            </button>

            {openStrategicDbTableSelectColId === `strategic_${field}` && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-[#151518] border border-[#2B2B30] rounded shadow-2xl z-50 flex flex-col max-h-[160px] overflow-hidden text-right">
                <div className="p-1.5 border-b border-[#232326] flex items-center gap-1 bg-[#0E0E10]">
                  <Search size={10} className="text-zinc-500 shrink-0 ml-1" />
                  <input
                    type="text"
                    value={strategicDbTableSearch}
                    onChange={(e) => setStrategicDbTableSearch(e.target.value)}
                    placeholder={isRtl ? "جستجو..." : "Search..."}
                    className="bg-transparent border-none text-[9px] text-white w-full outline-none p-0.5"
                    onClick={(e) => e.stopPropagation()}
                  />
                </div>
                <div className="overflow-y-auto flex-1 py-1 custom-scrollbar">
                  {(() => {
                    const list = [
                      { id: 'document_control_table', label: isRtl ? '📝 کنترل مستندات (ISO9001)' : '📝 Doc Control', isCore: true },
                      { id: 'indicators_table', label: isRtl ? '📊 شاخص‌های کلیدی (KPI)' : '📊 KPI Indicators', isCore: true },
                      { id: 'documents_table', label: isRtl ? '📂 مستندات و فرم‌ها (QMS)' : '📂 Custom Docs', isCore: true },
                      { id: 'clause_links_table', label: isRtl ? '📚 لینک‌های بند سازمانی' : '📚 Clause Links', isCore: true },
                      { id: 'strategic_evaluations_table', label: isRtl ? '🎯 ارزیابی استراتژیک (SWOT/PESTEL)' : '🎯 Strategic SWOT/PEST', isCore: true },
                      { id: 'strategic_items_table', label: isRtl ? '🎯 کارت‌های برنامه‌ریزی استراتژیک' : '🎯 Strategic Cards', isCore: true },
                      { id: 'nc_items_table', label: isRtl ? '🛠️ اقدامات اصلاحی و عدم انطباق‌ها (CAPA)' : '🛠️ CAPA Corrective Actions', isCore: true },
                      { id: 'records_table', label: isRtl ? '⚙️ آرشیو سوابق و مستندات' : '⚙️ Archives & Records', isCore: true },
                      { id: 'csr_mappings_table', label: isRtl ? '🗂️ مقایسه الزامات خاص مشتریان (CSR)' : '🗂️ Customer Specific Requirements (CSR)', isCore: true },
                      { id: 'process_mappings_table', label: isRtl ? '🗺️ نقشه فرآیندهای سازمانی' : '🗺️ Process Mapping Matrix', isCore: true },
                      { id: 'kpi_vars_table', label: isRtl ? '📈 متغیرهای محاسباتی آمارها' : '📈 KPI Variables', isCore: true },
                      { id: 'strategic_threshold_matrix_table', label: isRtl ? '⚙️ تنظیمات آستانه ماتریس ریسک' : '⚙️ Strategic Threshold Matrix', isCore: true }
                    ];
                    try {
                      const docsGroup = QmsDatabase.selectAll('documents_table') || {};
                      Object.keys(docsGroup).forEach(title => {
                        list.push({
                          id: `doc_${title}`,
                          label: isRtl ? `📋 سند: ${title}` : `📋 Document: ${title}`,
                          isCore: false
                        });
                      });
                    } catch (e) {}

                    const mappedList = list.map(t => {
                      let searchName = t.id;
                      if (t.id.startsWith('doc_')) {
                        searchName = t.id.substring(4);
                      } else {
                        if (t.id === 'document_control_table') searchName = 'کنترل مستندات';
                        else if (t.id === 'indicators_table') searchName = 'شاخص‌های کلیدی عملکرد (KPI)';
                        else if (t.id === 'documents_table') searchName = 'مستندات و فرم‌ها';
                        else if (t.id === 'clause_links_table') searchName = 'لینک‌های بند سازمانی';
                        else if (t.id === 'strategic_evaluations_table') searchName = 'ارزیابی استراتژیک';
                        else if (t.id === 'nc_items_table') searchName = 'اقدامات اصلاحی و عدم انطباق‌ها';
                        else if (t.id === 'process_mappings_table') searchName = 'نقشه فرآیندهای سازمان';
                        else if (t.id === 'records_table') searchName = 'آرشیو سوابق و مستندات';
                        else if (t.id === 'csr_mappings_table') searchName = 'مقایسه الزامات خاص مشتریان (CSR)';
                        else if (t.id === 'kpi_vars_table') searchName = 'متغیرهای محاسباتی آمارها';
                        else if (t.id === 'strategic_threshold_matrix_table') searchName = 'تنظیمات آستانه ماتریس ریسک';
                      }
                      const clauseNo = getClauseNumberForDocument(searchName);
                      return { ...t, clauseNumber: clauseNo };
                    });

                    const filtered = mappedList.filter(t => {
                      if (!strategicDbTableSearch) return true;
                      const query = strategicDbTableSearch.toLowerCase();
                      return (
                        t.label.toLowerCase().includes(query) ||
                        t.id.toLowerCase().includes(query) ||
                        (t.clauseNumber && t.clauseNumber.toLowerCase().includes(query))
                      );
                    });

                    return filtered.map(t => (
                      <button
                        key={t.id}
                        type="button"
                        onClick={() => {
                          updateStrategicDbConfig(field, { dbTable: t.id, dbColumn: '' });
                          setOpenStrategicDbTableSelectColId(null);
                          setStrategicDbTableSearch('');
                        }}
                        className={`w-full text-right px-2 py-1.5 hover:bg-amber-500/10 hover:text-white flex items-center justify-between text-[8px] border-b border-white/5 last:border-0 cursor-pointer ${config.dbTable === t.id ? 'bg-amber-500/10 text-amber-400 font-bold' : 'text-[#A0A0AA]'}`}
                      >
                        <span className="truncate">{t.label}</span>
                        {t.clauseNumber && (
                          <span className="bg-emerald-500/15 text-emerald-400 px-1 py-0.5 rounded text-[7px] font-bold shrink-0 mr-1 font-mono">
                            {isRtl ? `بند ${t.clauseNumber}` : `Cl. ${t.clauseNumber}`}
                          </span>
                        )}
                      </button>
                    ));
                  })()}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Database Column Select */}
        {config.dbTable && (
          <div className="flex flex-col gap-1">
            <span className="text-[#65656F] text-[8px] font-bold">{isRtl ? 'ستون هدف مبدا:' : 'Database Column:'}</span>
            <select
              value={config.dbColumn || ''}
              onChange={(e) => updateStrategicDbConfig(field, { dbColumn: e.target.value })}
              className="bg-[#1A1A1C] border border-[#232326] text-[9px] text-white p-1 rounded outline-none w-full text-right cursor-pointer"
            >
              <option value="">{isRtl ? '-- انتخاب ستون دیتابیس --' : '-- Choose Column --'}</option>
              {(() => {
                const colsSet = new Set<string>();
                if (config.dbTable.startsWith('doc_')) {
                  const targetDocName = config.dbTable.substring(4);
                  const tpl = documentTemplates[targetDocName];
                  if (tpl) {
                    getInitialColumns(tpl).forEach(c => {
                      const fld = c.field || c.id;
                      if (fld && fld !== 'id' && !fld.endsWith('_fk')) {
                        colsSet.add(fld);
                      }
                    });
                  }
                  try {
                    const draftItemsRaw = localStorage.getItem(`iatf_draft_items_${targetDocName}`);
                    if (draftItemsRaw) {
                      const itemsObj = JSON.parse(draftItemsRaw);
                      if (Array.isArray(itemsObj)) {
                        itemsObj.forEach(item => {
                          Object.keys(item).forEach(k => {
                            if (k.startsWith('custom_')) colsSet.add(k);
                          });
                        });
                      }
                    }
                  } catch {}
                } else {
                  const dbTableData = QmsDatabase.selectAll(config.dbTable as any) || {};
                  if (config.dbTable === 'document_control_table') {
                    ['code', 'revision', 'preparedBy', 'approvedBy', 'lifecycle_status'].forEach(c => colsSet.add(c));
                  } else if (config.dbTable === 'indicators_table') {
                    ['type', 'titleFa', 'titleEn', 'clauseId', 'target', 'unit', 'formula'].forEach(c => colsSet.add(c));
                  } else if (config.dbTable === 'documents_table') {
                    ['rowCount', 'lastUpdatedTime'].forEach(c => colsSet.add(c));
                  } else if (config.dbTable === 'clause_links_table') {
                    ['documents_list'].forEach(c => colsSet.add(c));
                  } else if (config.dbTable === 'strategic_evaluations_table') {
                    ['id', 'title', 'desc', 'source', 'clause', 'impactCustomer', 'impactQuality', 'impactProcess', 'impactGoals', 'impactLegal', 'probability', 'nature'].forEach(c => colsSet.add(c));
                  } else if (config.dbTable === 'strategic_items_table') {
                    ['id', 'title', 'description', 'isActive', 'clauseNumber', 'lastReview'].forEach(c => colsSet.add(c));
                  } else if (config.dbTable === 'nc_items_table') {
                    ['id', 'clauseId', 'clauseNumber', 'clauseTitle', 'description', 'declaredAt', 'source', 'reporter', 'targetDate', 'status', 'delayReason'].forEach(c => colsSet.add(c));
                  }
                  Object.values(dbTableData).forEach((rowVal: any) => {
                    if (rowVal && typeof rowVal === 'object') {
                      Object.keys(rowVal).forEach(k => {
                        if (k !== 'id' && k !== 'index' && !k.endsWith('_fk')) colsSet.add(k);
                      });
                    }
                  });
                }

                return Array.from(colsSet).map(c => {
                  const friendly = getSharedColumnFriendlyName(c, config.dbTable || '');
                  return (
                    <option key={c} value={c}>
                      {friendly}
                    </option>
                  );
                });
              })()}
            </select>
          </div>
        )}

        {/* Sync Buttons */}
        {config.dbTable && config.dbColumn && (
          <div className="flex flex-col gap-1.5 mt-1 pt-1.5 border-t border-white/5">
            <button
              type="button"
              onClick={() => {
                handleBulkLoadDbRows(virtualCol);
                alert(isRtl ? 'تمام سطرهای متناظر مرجع بارگذاری شدند.' : 'All rows populated successfully.');
                setOpenStrategicDbColId(null);
              }}
              className="flex items-center justify-center gap-1 bg-amber-500/15 hover:bg-amber-500/25 border border-amber-500/30 text-[9px] text-amber-400 py-1.5 px-2 rounded cursor-pointer font-bold transition w-full"
            >
              <PlayCircle size={10} className="text-amber-400 animate-pulse" />
              <span>{isRtl ? '⚡ بارگذاری و همگام‌سازی ردیف‌های مبدا' : '⚡ Populate & Sync Rows'}</span>
            </button>

            <button
              type="button"
              onClick={() => {
                updateStrategicDbConfig(field, { dbTable: '', dbColumn: '' });
                setOpenStrategicDbColId(null);
                alert(isRtl ? 'ارتباط دیتابیس با موفقیت قطع شد.' : 'Database link disconnected successfully.');
              }}
              className="flex items-center justify-center gap-1 bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 text-[9px] text-red-400 py-1 px-2 rounded cursor-pointer transition w-full"
            >
              <span>{isRtl ? '❌ قطع اتصال دیتابیس' : '❌ Disconnect Database Link'}</span>
            </button>
          </div>
        )}

        {/* Protection disclaimer */}
        <div className="bg-amber-500/5 border border-amber-500/10 text-[7.5px] text-amber-400/90 p-1.5 rounded leading-relaxed mt-1">
          <span>{isRtl ? '⚠️ اصل حفاظتی عدم دستکاری دیتابیس فعال است. تغییرات را از مرجع اعمال کنید.' : 'Database protection is active. Edit in the reference table.'}</span>
        </div>
      </div>,
      document.body
    );
  };

  React.useEffect(() => {
    if (initialRiskActiveViewTab) {
      setRiskActiveViewTab(initialRiskActiveViewTab);
    }
  }, [initialRiskActiveViewTab]);

  // Process-Risk Clauses Matrix States & Variables
  const [activeRiskClauses, setActiveRiskClauses] = React.useState<any[]>([]);
  const [riskClauseMappings, setRiskClauseMappings] = React.useState<Record<string, string[]>>({});
  const [editingRiskClause, setEditingRiskClause] = React.useState<any | null>(null);
  const [isAddingRiskClause, setIsAddingRiskClause] = React.useState<boolean>(false);
  const [newRiskClauseId, setNewRiskClauseId] = React.useState<string>('');
  const [newRiskClauseTitle, setNewRiskClauseTitle] = React.useState<string>('');
  const [newRiskClauseText, setNewRiskClauseText] = React.useState<string>('');
  const [riskClauseSearchQuery, setRiskClauseSearchQuery] = useState<string>('');

  // Update Process-Risk Clause Matrix helper
  const updateRiskClauseMatrix = (newMappings: Record<string, string[]>, newClauses?: any[]) => {
    setRiskClauseMappings(newMappings);
    localStorage.setItem('process_risk_clauses_matrix', JSON.stringify(newMappings));

    if (newClauses) {
      setActiveRiskClauses(newClauses);
      localStorage.setItem('qms_active_risk_clauses', JSON.stringify(newClauses));
    }

    // Persist to QmsDatabase
    try {
      const qmsSaved = QmsDatabase.selectAll(QmsDatabase.TABLES.PROCESS_MAPPINGS) || {};
      qmsSaved.risk_clauses_mapping = newMappings;
      QmsDatabase.writeAll(QmsDatabase.TABLES.PROCESS_MAPPINGS, qmsSaved);
    } catch (e) {
      console.error('Failed syncing to process_mappings_table:', e);
    }
  };

  const getProcessRequirementsRows = (): any[] => {
    try {
      const dbSaved = QmsDatabase.selectRow<any[]>('documents_table', 'ماتریس فرآیندها-الزامات') || 
                      QmsDatabase.selectRow<any[]>('documents_table', 'ماتریس فرآیندها-الزامات (Process-Requirements Matrix)');
      if (dbSaved && dbSaved.length > 0) return dbSaved;

      try {
        const dbDocs = QmsDatabase.selectAll('documents_table') || {};
        const refRows = dbDocs['ماتریس فرآیندها-الزامات'] || dbDocs['ماتریس فرآیندها-الزامات (Process-Requirements Matrix)'];
        if (refRows && refRows.length > 0) return refRows;
      } catch {}

      const rawMatrix = localStorage.getItem('iatf_draft_items_ماتریس فرآیندها-الزامات') || 
                        localStorage.getItem('iatf_draft_items_ماتریس فرآیندها-الزامات (Process-Requirements Matrix)');
      if (rawMatrix) {
        const draftRows = JSON.parse(rawMatrix);
        if (draftRows && draftRows.length > 0) return draftRows;
      }
    } catch (e) {
      console.error('Error fetching process requirements row list:', e);
    }
    return [];
  };

  // Auto-seed missing risks for mapped clauses to ensure 100% standard compliance
  React.useEffect(() => {
    if (template.smartType !== 'RISK_MANAGEMENT') return;
    if (Object.keys(riskClauseMappings).length === 0 || activeRiskClauses.length === 0) return;

    let changed = false;
    const nextItems = [...items];

    (Object.entries(riskClauseMappings) as [string, string[]][]).forEach(([procName, mappedClauses]) => {
      mappedClauses.forEach(cid => {
        const hasRisk = nextItems.some(
          i => i.type === 'risk_and_opp' && 
               i.associatedProcess === procName && 
               i.clauseId === cid
        );

        if (!hasRisk) {
          const clause = activeRiskClauses.find(c => c.id === cid);
          const clauseTitle = clause ? clause.title : '';
          const defaultRiskText = isRtl 
            ? `ریسک عدم برآورده‌سازی کامل الزامات بند ${cid} (${clauseTitle || 'مدیریت ریسک'}) در فرآیند ${procName}`
            : `Risk of partial non-compliance with clause ${cid} (${clauseTitle || 'Risk'}) in ${procName} process`;
          const defaultOppText = isRtl
            ? `بهبود اثربخشی فرآیند ${procName} فراتر از الزامات بند ${cid} و افزایش چابکی`
            : `Improve efficiency of ${procName} beyond clause ${cid} requirements`;
          
          const defaultRiskAction = isRtl
            ? `تدوین دستورالعمل‌های استاندارد منطبق بر بند ${cid} و پایش کیفی دوره‌ای`
            : `Establish SOPs compliant with clause ${cid} and run periodic internal audits`;
          
          const defaultOppAction = isRtl
            ? `دیجیتالی‌سازی و اتوماسیون فرآیندها با رویکرد تفکر مبتنی بر ریسک`
            : `Process automation and digital workflows with risk-based thinking`;

          const newRisk: DocItem = {
            id: `risk-auto-${procName}-${cid}-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
            associatedProcess: procName,
            type: 'risk_and_opp',
            clauseId: cid,
            field1: defaultRiskText,
            numeric1: 3,
            numeric2: 3,
            numeric3: 9,
            field2: defaultRiskAction,
            numeric4: 2,
            numeric5: 2,
            numeric6: 4,
            field3: defaultOppText,
            field4: defaultOppAction
          };
          nextItems.push(newRisk);
          changed = true;
        }
      });
    });

    if (changed) {
      setItems(nextItems);
      localStorage.setItem(`iatf_draft_items_${template.title}`, JSON.stringify(nextItems));
      saveDocument(nextItems);
    }
  }, [riskClauseMappings, activeRiskClauses, template.smartType]);

  // Automated intelligent risks & opportunities generation using backend Gemini API
  const handleGenerateRisksOpportunities = async (procName: string, contextRows: any[]) => {
    try {
      setGeneratingRisksFor(procName);
      const associatedClauses = riskClauseMappings[procName] || [];
      const response = await fetch('/api/generate-risks-opportunities', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          processName: procName,
          contextRows: contextRows,
          associatedClauses: associatedClauses,
          model: editorAiModel
        })
      });

      if (!response.ok) {
        throw new Error('فراخوانی سرور با خطا مواجه شد.');
      }

      const resJson = await response.json();
      if (resJson.success && Array.isArray(resJson.data)) {
        // filter out existing 'risk_and_opp' entries for this specific process with the newly generated ones
        const unchanged = items.filter(idx => !(idx.type === 'risk_and_opp' && idx.associatedProcess === procName));
        const updated = [...unchanged, ...resJson.data];
        setItems(updated);
        localStorage.setItem(`iatf_draft_items_${template.title}`, JSON.stringify(updated));
        saveDocument(updated);
      } else {
        throw new Error(resJson.error || 'ساختار پاسخ نامعتبر است.');
      }
    } catch (err: any) {
      console.error('Error in AI Generate risks:', err);
      alert(isRtl ? 'قفل هوشمند بازیابی ریسک با خطا مواجه شد. در فاز آفلاین سوابق مهندسی استفاده گردید.' : 'Server connection failed, using local historical risk configurations instead.');
    } finally {
      setGeneratingRisksFor('');
    }
  };

  // Control Plan Senior QA/QC Expert AI Helper Methods
