  // Auto-sync processes from the Process Specification (Turtle) document to Process Map
  React.useEffect(() => {
    if (isOpen && isProcessMap) {
      const available = getAvailableProcesses();
      if (available.length === 0) return;

      let currentItems = [...items];
      let changed = false;

      // 1. Find which available processes are NOT in the current layout
      const existingProcessIds = new Set(
        currentItems
          .map(it => it.processId || '')
          .filter(Boolean)
      );
      
      const existingTitles = new Set(
        currentItems
          .map(it => (it.field1 || '').trim().toLowerCase())
          .filter(Boolean)
      );

      const missingProcs = available.filter(p => 
        !existingProcessIds.has(p.id) && 
        !existingTitles.has((p.title || '').trim().toLowerCase())
      );

      if (missingProcs.length > 0) {
        changed = true;
        // Append missing ones
        const startIdx = currentItems.length;
        const newNodes = missingProcs.map((p, idx) => {
          const globalIdx = startIdx + idx;
          return {
            id: 'node-' + Date.now() + '-' + globalIdx + '-' + Math.random().toString(36).substr(2, 4),
            processId: p.id,
            field1: p.title,
            field2: p.inputs,
            field3: p.outputs,
            field4: p.kpi,
            x: 40 + (globalIdx % 3) * 280,
            y: 45 + Math.floor(globalIdx / 3) * 170,
            connections: [],
            connectionsOffsets: {}
          };
        });
        currentItems = [...currentItems, ...newNodes];
      }

      // 2. Also ensure inputs/outputs of existing matching nodes are kept in sync
      currentItems = currentItems.map(node => {
        const found = available.find(p => p.id === node.processId || (p.title || '').trim().toLowerCase() === (node.field1 || '').trim().toLowerCase());
        if (found) {
          if (node.field2 !== found.inputs || node.field3 !== found.outputs || node.field4 !== found.kpi) {
            changed = true;
            return {
              ...node,
              field2: found.inputs,
              field3: found.outputs,
              field4: found.kpi
            };
          }
        }
        return node;
      });

      // 3. Re-calculate connections based on input-output overlap keywords automatically
      // if we added any new nodes, or to ensure connections are dynamically fresh!
      if (changed || currentItems.some(it => !it.connections || it.connections.length === 0)) {
        currentItems = currentItems.map(node => {
          const discoveredConnections = [...(node.connections || [])];
          
          currentItems.forEach(otherNode => {
            if (otherNode.id === node.id) return;
            
            // Clean and tokenize outputs and inputs using standard Persian/English punctuation
            const outputsOfA = (node.field3 || '').split(/[\s،,و\-\/؛;:]+/).map(w => w.trim()).filter(w => w.length > 2);
            const inputsOfB = (otherNode.field2 || '');
            
            const isConnected = outputsOfA.some(word => {
              if (word.toLowerCase().includes('خروجی') || word.toLowerCase().includes('انتهای') || word.toLowerCase().includes('کیلو') || word.toLowerCase().includes('سند')) return false;
              return inputsOfB.toLowerCase().includes(word.toLowerCase());
            });

            if (isConnected && !discoveredConnections.includes(otherNode.id)) {
              discoveredConnections.push(otherNode.id);
            }
          });

          return {
            ...node,
            connections: Array.from(new Set(discoveredConnections))
          };
        });
        
        changed = true;
      }

      if (changed) {
        setItems(currentItems);
        localStorage.setItem(`iatf_draft_items_${template.title}`, JSON.stringify(currentItems));
      }
    }
  }, [isOpen, isProcessMap, template.title]);

