                                                      <option value="">--</option>
                                                      {(() => {
                                                        const processClauses = riskClauseMappings[procName] || [];
                                                        let filtered = processClauses.length > 0
                                                          ? activeRiskClauses.filter(rc => processClauses.includes(rc.id))
                                                          : activeRiskClauses;
                                                        
                                                        // If current clauseId exists but is not in filtered, include it
                                                        if (item.clauseId && !filtered.some(rc => rc.id === item.clauseId)) {
                                                          const extraClause = activeRiskClauses.find(rc => rc.id === item.clauseId);
                                                          if (extraClause) {
                                                            filtered = [...filtered, extraClause];
                                                          } else {
                                                            filtered = [...filtered, { id: item.clauseId, title: '' }];
                                                          }
                                                        }
                                                        
                                                        return filtered.map(rc => (
                                                          <option key={rc.id} value={rc.id} title={rc.title}>{rc.id}</option>
                                                        ));
                                                      })()}
